import {analysis,composition,CONDITIONS,quotient,direction} from './equilibrium-model.js';
export function equilibriumQuestions(s){
 const a=analysis(s),x=a?.value??.00012,fe=a?.row.feTotal??.0005,scn=a?.row.scnTotal??.0005;
 const usable=a&&!a.extrapolated,fit=usable?a.fit:{slope:4600,intercept:.001},absorbance=usable?a.row.absorbance:.553,c=usable?x:(absorbance-fit.intercept)/fit.slope;
 return[
 {prompt:'What does a stable colour in an equilibrium mixture establish by itself?',answers:['It shows no visible concentration change; continuing reactions need a dynamic explanation.','It shows the forward reaction stopped and all reactants were consumed.','It shows the forward rate is zero while the reverse reaction continues.'],hint:'Dynamic equilibrium has equal, non-zero forward and reverse rates. Colour alone cannot demonstrate those rates.'},
 {prompt:`${usable?'Use your recorded absorbance and calibration.':'Supplied example (a usable in-range calibration and mixture reading were not recorded):'} A = mc + b, m = ${fit.slope.toPrecision(9)} dm³ mol⁻¹, b = ${fit.intercept.toPrecision(9)}, A = ${absorbance.toFixed(3)}. Calculate equilibrium [FeSCN²⁺].`,fields:[{id:'value',label:'Complex concentration / mol dm⁻³',answer:c,tolerance:Math.max(1e-8,c*.01)}],hint:'Use c = (A − b)/m; a good-looking line does not prove correct preparation.'},
 {prompt:`${usable?'Use your recorded aliquot.':'Supplied example:'} The aliquot volume is ${(usable?a.row.volume:3).toFixed(4)} mL and analytical Fe total is ${(usable?fe:.0005).toPrecision(9)} mol dm⁻³. Calculate total moles of Fe (free plus complexed) in this aliquot.`,fields:[{id:'value',label:'Total Fe / mol',answer:(usable?fe:.0005)*(usable?a.row.volume:3)/1000,tolerance:1e-9}],hint:'Use n = cV with V in dm³. This total includes free and complexed iron; Kc and free equilibrium composition are in the optional HL section.'}

 ];
}
export function hlEquilibrium(s){const a=analysis(s);if(!a||a.extrapolated)return null;const change=s.lastMixtureChange;return{a,change,Q:change?.Q,direction:change?.direction};}
export const equilibriumAssumptions=`Fixed 25 °C; a closed, well-mixed aliquot between additions; one dominant 1:1 complex; analytical Fe and SCN totals conserved; additive volumes and ideal concentrations in a matrix-matched 0.10 M HNO₃ solvent. All stock/reference/solvent additions share that matrix. Kc = ${CONDITIONS.Kc} dm³ mol⁻¹ and optical coefficients are illustrative teaching constants, not experimentally validated conditional data. Colour and absorbance are attributed to the complex; free-ion/background absorption is omitted. Hydrolysis, other iron–thiocyanate complexes, activities and temperature dependence are omitted. Equilibration is algebraic, not a measured relaxation-time simulation. At equilibrium both reaction directions continue at equal rates; stable colour alone is not evidence of continuing microscopic reactions.`;
